// Beat [6] — YubiKeys as HIDs: a HID is just a keyboard (the key pretends to be one).
private val otpKeys = listOf(
    "cccccdbbjbvvlvbgufrienrreugdbedfjkgglccjtljn",
    "cccccdbbjbvvetfejvhdullklkrgkegtdcvnjciiidcr",
    "cccccdbbjbvvkntgbfcgkvhkckgncjrftrvjcjnhubet"
)

val hid by Slide(stepCount = 5, specs = SlideSpecs(size = SLIDE_SIZE_16_9)) { step ->
    val sweep by animateFloatAsState(
        targetValue = if (step >= 4) 1f else 0f,
        animationSpec = spring(stiffness = Spring.StiffnessLow),
        label = "invalidate"
    )
    // Header (title + subtitle + keyboard line) collapses to 0 height at step 3 so the
    // rest of the content slides up — same reflow trick as the hamlet image, reversed.
    val headerReveal by animateFloatAsState(
        targetValue = if (step >= 3) 0f else 1f,
        animationSpec = spring(stiffness = Spring.StiffnessLow),
        label = "header"
    )
    Column(
        modifier = Modifier.fillMaxSize().padding(16.dp),
        verticalArrangement = Arrangement.spacedBy(10.dp, Alignment.CenterVertically),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        // Header — always in the layout; its height animates full -> 0 at step 3.
        Column(
            modifier = Modifier
                .layout { measurable, constraints ->
                    val placeable = measurable.measure(constraints)
                    layout(constraints.maxWidth, (placeable.height * headerReveal).toInt()) {
                        placeable.place((constraints.maxWidth - placeable.width) / 2, 0)
                    }
                }
                .clip(RectangleShape)
                .alpha(headerReveal),
            verticalArrangement = Arrangement.spacedBy(10.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Text(
                text = "HID",
                style = MaterialTheme.typography.displaySmall,
                fontWeight = FontWeight.Bold
            )
            Text(
                text = "Human Interface Device",
                style = MaterialTheme.typography.titleMedium,
                color = MaterialTheme.colorScheme.onSurfaceVariant
            )
            // Step 1 — HID means: a keyboard (it pretends to be one).
            androidx.compose.animation.AnimatedVisibility(
                visible = step >= 1,
                enter = fadeIn(spring(stiffness = Spring.StiffnessMediumLow))
            ) {
                Text(
                    text = "= a keyboard (or it pretends to be one)",
                    style = MaterialTheme.typography.headlineSmall,
                    color = MaterialTheme.colorScheme.primary
                )
            }
        }
        // Step 2 — in OTP mode, it literally types these strings in.
        androidx.compose.animation.AnimatedVisibility(
            visible = step >= 2,
            enter = fadeIn(spring(stiffness = Spring.StiffnessMediumLow))
        ) {
            Column(
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(4.dp)
            ) {
                Text(
                    text = "In OTP mode, it literally types these strings:",
                    style = MaterialTheme.typography.titleMedium,
                    color = MaterialTheme.colorScheme.onSurface
                )
                otpKeys.forEach { key ->
                    Text(
                        text = key,
                        fontSize = 14.sp,
                        fontFamily = FontFamily.Monospace,
                        color = MaterialTheme.colorScheme.onSurface
                    )
                }
            }
        }
        // Steps 3-4 — replay defence: the attacker saves keys, then validating the
        // newest retroactively invalidates every earlier one (even the saved copies).
        androidx.compose.animation.AnimatedVisibility(
            visible = step >= 3,
            enter = fadeIn(spring(stiffness = Spring.StiffnessMediumLow))
        ) {
            Column(
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                Text(
                    text = if (step >= 4)
                        "validating a key retroactively invalidates every earlier one — even the saved copies"
                    else
                        "an attacker copies each key as it's typed, saving them for replay",
                    style = MaterialTheme.typography.titleSmall,
                    color = MaterialTheme.colorScheme.onSurfaceVariant
                )
                Row(
                    horizontalArrangement = Arrangement.spacedBy(14.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    for (i in 0 until 5) {
                        val state = when {
                            i == 4 -> if (step >= 4) KeyState.Accepted else KeyState.Copied
                            step < 4 -> KeyState.Copied
                            sweep >= (4 - i) / 4f -> KeyState.Invalid
                            else -> KeyState.Copied
                        }
                        KeyGlyphState(state)
                    }
                    Icon(
                        imageVector = Icons.AutoMirrored.Filled.ArrowRight,
                        contentDescription = null,
                        tint = MaterialTheme.colorScheme.primary,
                        modifier = Modifier.size(20.dp)
                    )
                }
            }
        }
    }
}

private enum class KeyState { Copied, Accepted, Invalid }

private data class GlyphStyle(
    val rectColor: Color,
    val accent: Color,
    val bold: Boolean,
    val marker: String? = null,
    val icon: ImageVector? = null
)

/** A small key-glyph placeholder (rectangle) in one of three states. */
@Composable
private fun KeyGlyphState(state: KeyState) {
    val style = when (state) {
        KeyState.Copied -> GlyphStyle(
            rectColor = MaterialTheme.colorScheme.surfaceVariant,
            accent = MaterialTheme.colorScheme.onSurfaceVariant,
            bold = false,
            marker = "saved"
        )
        KeyState.Accepted -> GlyphStyle(
            rectColor = MaterialTheme.colorScheme.primaryContainer,
            accent = MaterialTheme.colorScheme.primary,
            bold = true,
            icon = Icons.Default.Check
        )
        KeyState.Invalid -> GlyphStyle(
            rectColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.4f),
            accent = MaterialTheme.colorScheme.onSurfaceVariant,
            bold = false,
            icon = Icons.Default.Close
        )
    }
    Column(
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(2.dp)
    ) {
        Box(
            modifier = Modifier
                .size(30.dp)
                .clip(RoundedCornerShape(6.dp))
                .background(style.rectColor)
        )
        Box(
            modifier = Modifier
                .width(48.dp)
                .height(18.dp),
            contentAlignment = Alignment.Center
        ) {
            if (style.icon != null) {
                Icon(
                    imageVector = style.icon,
                    contentDescription = null,
                    tint = style.accent,
                    modifier = Modifier.size(14.dp)
                )
            } else {
                Text(
                    text = style.marker ?: "",
                    fontSize = 14.sp,
                    color = style.accent,
                    fontWeight = if (style.bold) FontWeight.Bold else FontWeight.Normal,
                    textAlign = TextAlign.Center
                )
            }
        }
    }
}
