// Beat [2] — asymmetric crypto: the standard key-exchange picture.
// Alice and Bob each KEEP their private key and HAND OUT their public key.
// (Rounded rectangles are placeholders for future image assets — avatars /
// key glyphs — to be swapped in later.)

// Scene 1 bit-fluff: arbitrary 0/1 strings — this step is illustrative, not arithmetic.
// Laid out as a tall, narrow column (one bit per line, lineHeight squeezed) so the two
// blocks fit the slide width.
private val plainBits: String = "0110100111010110"
private val cipherBits: String = "1001101000101101"

val aliceBob by Slide(stepCount = 4, specs = SlideSpecs(size = SLIDE_SIZE_16_9)) { step ->
    Box(modifier = Modifier.fillMaxSize()) {
        // Scene 0 — Alice generates her private/public key-pair.
        androidx.compose.animation.AnimatedVisibility(
            visible = step < 1,
            modifier = Modifier.align(Alignment.Center),
            enter = fadeIn(spring(stiffness = Spring.StiffnessMediumLow)),
            exit = fadeOut(spring(stiffness = Spring.StiffnessMediumLow))
        ) {
            AliceKeypairScene()
        }

        // Scene 1 — public key encrypts; private key is the inverse (the round-trip).
        // Alice is gone — the two keys now ride the arrows: public forward, private back.
        androidx.compose.animation.AnimatedVisibility(
            visible = step >= 1 && step < 2,
            modifier = Modifier.align(Alignment.Center),
            enter = fadeIn(spring(stiffness = Spring.StiffnessMediumLow)),
            exit = fadeOut(spring(stiffness = Spring.StiffnessMediumLow))
        ) {
            EncryptDecryptScene()
        }

        // Scene 2 — the math behind a public key: one of two hard problems.
        androidx.compose.animation.AnimatedVisibility(
            visible = step >= 2 && step < 3,
            modifier = Modifier.align(Alignment.Center),
            enter = fadeIn(spring(stiffness = Spring.StiffnessMediumLow)),
            exit = fadeOut(spring(stiffness = Spring.StiffnessMediumLow))
        ) {
            MethodsScene()
        }

        // Scene 3 — Alice & Bob exchange public keys (private keys stay).
        androidx.compose.animation.AnimatedVisibility(
            visible = step >= 3,
            modifier = Modifier.fillMaxSize(),
            enter = fadeIn(spring(stiffness = Spring.StiffnessMediumLow)),
            exit = fadeOut(spring(stiffness = Spring.StiffnessMediumLow))
        ) {
            Column(
                modifier = Modifier.fillMaxSize().padding(16.dp),
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                Text(
                    text = "Private stays. Public travels.",
                    style = MaterialTheme.typography.headlineSmall,
                    color = MaterialTheme.colorScheme.onSurfaceVariant
                )

                Row(
                    modifier = Modifier.fillMaxWidth().weight(1f),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Person(Icons.Default.Girl, "Alice")
                    Exchange()
                    Person(Icons.Default.Boy, "Bob")
                }
            }
        }
    }
}

/** Scene 0: Alice generates her private/public key-pair (before the exchange). Her circle is a person-image placeholder (consistent with the secretSanta ring nodes). */
@Composable
private fun AliceKeypairScene() {
    Row(
        modifier = Modifier.padding(16.dp),
        horizontalArrangement = Arrangement.spacedBy(20.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        Box(
            modifier = Modifier
                .size(64.dp)
                .clip(CircleShape)
                .background(MaterialTheme.colorScheme.surfaceVariant),
            contentAlignment = Alignment.Center
        ) {
            Text(
                text = "Alice",
                style = MaterialTheme.typography.labelLarge,
                color = MaterialTheme.colorScheme.onSurfaceVariant
            )
        }
        Icon(
            imageVector = Icons.AutoMirrored.Filled.ArrowRight,
            contentDescription = null,
            tint = MaterialTheme.colorScheme.onSurfaceVariant,
            modifier = Modifier.size(28.dp)
        )
        Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
            KeyCard("private key", "keep secret", isPrivate = true)
            KeyCard("public key", "share freely", isPrivate = false)
        }
    }
}

/** Scene 1: a public key encrypts bits; the private key is its inverse. Alice is gone, and the two keys now label the arrows — public (tertiary) forward to encrypt, private (primary) backward as the inverse. The accent colours mirror the KeyCard dots from Scene 0, so the keys read as repositioned, not new. */
@Composable
private fun EncryptDecryptScene() {
    Column(
        modifier = Modifier.fillMaxSize().padding(16.dp),
        verticalArrangement = Arrangement.spacedBy(16.dp),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Text(
            "Public key encrypts — private key is the inverse",
            style = MaterialTheme.typography.headlineSmall,
            color = MaterialTheme.colorScheme.onSurfaceVariant
        )
        Row(
            modifier = Modifier.fillMaxWidth().weight(1f),
            horizontalArrangement = Arrangement.spacedBy(64.dp, Alignment.CenterHorizontally),
            verticalAlignment = Alignment.CenterVertically
        ) {
            BitsBlock(label = "plaintext", bits = plainBits)
            Column(
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(48.dp)
            ) {
                // forward: encrypt with the public key (tertiary — matches the public KeyCard dot)
                Arrow(label = "public key", leftToRight = true, color = MaterialTheme.colorScheme.tertiary, sub = "encrypt")
                // backward: the inverse, using the private key (primary — matches the private KeyCard dot)
                Arrow(label = "private key", leftToRight = false, color = MaterialTheme.colorScheme.primary, sub = "the inverse")
            }
            BitsBlock(label = "ciphertext", bits = cipherBits, emphasized = true)
        }
    }
}

/** A labelled, monospaced block of "random" bits — a visual placeholder (no real arithmetic). */
@Composable
private fun BitsBlock(label: String, bits: String, emphasized: Boolean = false) {
    Column(horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(4.dp)) {
        Text(
            label,
            style = MaterialTheme.typography.labelSmall,
            color = MaterialTheme.colorScheme.onSurfaceVariant
        )
        Box(
            modifier = Modifier
                .clip(RoundedCornerShape(8.dp))
                .background(MaterialTheme.colorScheme.surfaceVariant)
                .padding(horizontal = 12.dp, vertical = 10.dp),
            contentAlignment = Alignment.Center
        ) {
            Text(
                text = bits.toCharArray().joinToString("\n"),
                fontSize = 14.sp,
                lineHeight = 12.sp,
                fontFamily = FontFamily.Monospace,
                fontWeight = if (emphasized) FontWeight.Bold else FontWeight.Normal,
                color = MaterialTheme.colorScheme.onSurface
            )
        }
    }
}

/** A labelled key card: an accent dot, a label, and a short subtitle. */
@Composable
private fun KeyCard(label: String, sub: String, isPrivate: Boolean) {
    val accent = if (isPrivate) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.tertiary
    Row(
        modifier = Modifier
            .width(170.dp)
            .clip(RoundedCornerShape(8.dp))
            .background(MaterialTheme.colorScheme.surfaceVariant)
            .padding(horizontal = 12.dp, vertical = 8.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        Box(Modifier.size(10.dp).clip(CircleShape).background(accent)) {}
        Column {
            Text(
                text = label,
                style = MaterialTheme.typography.labelLarge,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.onSurface
            )
            Text(
                text = sub,
                style = MaterialTheme.typography.labelSmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant
            )
        }
    }
}

/** Scene 2: a public key is built from one of two hard problems (image placeholders for each). */
@Composable
private fun MethodsScene() {
    Column(
        modifier = Modifier.fillMaxSize().padding(16.dp),
        verticalArrangement = Arrangement.spacedBy(16.dp),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Text(
            "Public-key crypto: two routes",
            style = MaterialTheme.typography.headlineSmall,
            color = MaterialTheme.colorScheme.onSurfaceVariant
        )
        Row(
            modifier = Modifier.fillMaxWidth().weight(1f),
            horizontalArrangement = Arrangement.spacedBy(24.dp, Alignment.CenterHorizontally),
            verticalAlignment = Alignment.CenterVertically
        ) {
            MethodCard("Modular exponentiation", "big-number arithmetic", Res.drawable.modular_exponentiation)
            MethodCard("Elliptic curves", "curve point arithmetic", Res.drawable.elliptic_curve)
        }
    }
}

/** One of the two methods: an illustration + label + subtitle. */
@Composable
private fun MethodCard(title: String, sub: String, image: DrawableResource) {
    Column(
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        Image(
            painter = painterResource(image),
            contentDescription = title,
            modifier = Modifier
                .size(220.dp)
                .clip(RoundedCornerShape(12.dp))
        )
        Text(
            title,
            style = MaterialTheme.typography.titleMedium,
            color = MaterialTheme.colorScheme.onSurface
        )
        Text(
            sub,
            style = MaterialTheme.typography.labelSmall,
            color = MaterialTheme.colorScheme.onSurfaceVariant
        )
    }
}

/** One party: a profile icon, a name, and the private key they keep. */
@Composable
private fun Person(icon: ImageVector, name: String) {
    Column(
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        Avatar(icon)
        Text(
            name,
            style = MaterialTheme.typography.titleMedium,
            color = MaterialTheme.colorScheme.onSurfaceVariant
        )
        PrivateKeyChip()
    }
}

/** A profile-picture avatar: a person icon in a rounded square. */
@Composable
private fun Avatar(icon: ImageVector) {
    Box(
        modifier = Modifier
            .size(80.dp)
            .clip(RoundedCornerShape(12.dp))
            .background(MaterialTheme.colorScheme.surfaceVariant),
        contentAlignment = Alignment.Center
    ) {
        Icon(
            imageVector = icon,
            contentDescription = null,
            tint = MaterialTheme.colorScheme.onSurfaceVariant,
            modifier = Modifier.size(48.dp)
        )
    }
}

/** The private key — highlighted (kept/locked); never handed out. */
@Composable
private fun PrivateKeyChip() {
    Box(
        modifier = Modifier
            .clip(RoundedCornerShape(8.dp))
            .background(MaterialTheme.colorScheme.primaryContainer)
            .padding(horizontal = 12.dp, vertical = 8.dp)
    ) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            // lock glyph placeholder (rectangle)
            Box(
                modifier = Modifier
                    .size(10.dp)
                    .clip(RoundedCornerShape(2.dp))
                    .background(MaterialTheme.colorScheme.onPrimaryContainer)
            )
            Spacer(Modifier.width(6.dp))
            Text(
                "private key — kept",
                style = MaterialTheme.typography.labelMedium,
                color = MaterialTheme.colorScheme.onPrimaryContainer
            )
        }
    }
}

/** The middle: the two public keys handed to each other. */
@Composable
private fun Exchange() {
    Column(
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(16.dp)
    ) {
        Arrow(label = "Alice's public key", leftToRight = true)
        Arrow(label = "Bob's public key", leftToRight = false)
    }
}

/** A labelled horizontal arrow; leftToRight picks the head side. color tints the shaft/head/label; sub is an optional caption below the label. */
@Composable
private fun Arrow(
    label: String,
    leftToRight: Boolean,
    color: Color = MaterialTheme.colorScheme.primary,
    sub: String? = null
) {
    Column(horizontalAlignment = Alignment.CenterHorizontally) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            if (!leftToRight) {
                Icon(imageVector = Icons.Default.ChevronLeft, contentDescription = null, tint = color, modifier = Modifier.size(28.dp))
            }
            Box(
                modifier = Modifier
                    .height(3.dp)
                    .width(96.dp)
                    .background(color)
            )
            if (leftToRight) {
                Icon(imageVector = Icons.Default.ChevronRight, contentDescription = null, tint = color, modifier = Modifier.size(28.dp))
            }
        }
        Text(
            label,
            style = MaterialTheme.typography.labelMedium,
            color = color
        )
        if (sub != null) {
            Text(
                sub,
                style = MaterialTheme.typography.labelSmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant
            )
        }
    }
}
