import yubikeys_pres.generated.resources.insomniac
import yubikeys_pres.generated.resources.mason
import yubikeys_pres.generated.resources.minion
import yubikeys_pres.generated.resources.robber
import yubikeys_pres.generated.resources.seer
import yubikeys_pres.generated.resources.tanner
