// Secret Santa as a functional graph: 11 people around a ring; each draws one
// name and gives to exactly one other person (a derangement — nobody gifts
// themselves). The directed edges are the assignment.
//
// This is the modular-exponentiation-mod-11 flavour: a map on a cyclic set of
// prime size, where "who gives to whom" is a permutation you can compute but
// (in the ZK version) do not reveal.
//
// assignment[i] = the person that person i gives to.
private val assignment = listOf(3, 7, 0, 5, 9, 1, 8, 10, 2, 6, 4) // a derangement of 0..10 (one 11-cycle)

// 4-bit data labels for crypto analogy view: 0000..1010
private val nodeBits = (0..10).map { it.toString(2).padStart(4, '0') }

// Once "sorted", every arrow points to the immediately-clockwise neighbour.
// sortedPos[i] = the ring slot (0..10) node i animates to (following the assignment cycle from 0).
private val sortedPos = listOf(0, 3, 10, 1, 6, 2, 8, 4, 9, 7, 5)

// The 11 Werewolf roles — node index -> (display name, avatar image).
private data class Role(val name: String, val image: DrawableResource)
private val roles = listOf(
    Role("Doppelgänger", Res.drawable.doppelganger),
    Role("Drunk", Res.drawable.drunk),
    Role("Hunter", Res.drawable.hunter),
    Role("Insomniac", Res.drawable.insomniac),
    Role("Mason", Res.drawable.mason),
    Role("Minion", Res.drawable.minion),
    Role("Robber", Res.drawable.robber),
    Role("Seer", Res.drawable.seer),
    Role("Tanner", Res.drawable.tanner),
    Role("Troublemaker", Res.drawable.troublemaker),
    Role("Werewolf", Res.drawable.werewolf)
)

val secretSanta by Slide(stepCount = 5, specs = SlideSpecs(size = SLIDE_SIZE_16_9)) { step ->
    val measurer = rememberTextMeasurer()
    val nodeFill = MaterialTheme.colorScheme.surfaceVariant
    val nodeBorder = MaterialTheme.colorScheme.onSurfaceVariant
    val arrowColor = MaterialTheme.colorScheme.primary
    val labelColor = MaterialTheme.colorScheme.onSurface
    val easyColor = Color(76f / 255f, 175f / 255f, 80f / 255f)       // green  — forward is easy
    val impossibleColor = Color(229f / 255f, 57f / 255f, 53f / 255f) // red    — inverse is "impossible"
    // 0 = tangled (index order), 1 = sorted (cycle order). Animates on step change.
    val sortT = animateFloatAsState(
        targetValue = if (step >= 2) 1f else 0f,
        animationSpec = tween(durationMillis = 900)
    ).value
    // Step 0 is just the ring (no arrows yet); the assignment arrows fade in at step 1.
    val arrowT = animateFloatAsState(
        targetValue = if (step >= 1) 1f else 0f,
        animationSpec = tween(durationMillis = 500)
    ).value
    // Highlight the 1->7 arrow ("easy to answer") from step 3.
    val easyT = animateFloatAsState(
        targetValue = if (step >= 3) 1f else 0f,
        animationSpec = tween(durationMillis = 500)
    ).value
    // Curved 7->1 arrow ("impossible") from step 4.
    val impossibleT = animateFloatAsState(
        targetValue = if (step >= 4) 1f else 0f,
        animationSpec = tween(durationMillis = 500)
    ).value

    var canvasSize by remember { mutableStateOf(IntSize.Zero) }
    var hoveredNode by remember { mutableStateOf<Int?>(null) }
    var isCryptoMode by remember { mutableStateOf(false) }

    val n = 11
    val cx = canvasSize.width / 2f
    val cy = canvasSize.height / 2f
    val ringR = min(canvasSize.width, canvasSize.height) * 0.34f
    val nodeR = min(canvasSize.width, canvasSize.height) * 0.045f

    val centers = remember(canvasSize, sortT) {
        if (canvasSize == IntSize.Zero) emptyList()
        else {
            (0 until n).map { i ->
                // Tangled (index order) -> sorted (cycle order); each node animates the short way around.
                val a0 = -PI / 2.0 + i * (2.0 * PI / n)
                val a1 = -PI / 2.0 + sortedPos[i] * (2.0 * PI / n)
                val d = a1 - a0
                val dn = ((d + PI) % (2.0 * PI) + 2.0 * PI) % (2.0 * PI) - PI // shortest signed delta, (-π, π]
                val a = (a0 + dn * sortT).toFloat()
                Offset(cx + cos(a) * ringR, cy + sin(a) * ringR)
            }
        }
    }

    Box(modifier = Modifier.fillMaxSize().padding(8.dp)) {
        // The assignment graph: 11 nodes in a ring, one outgoing arrow each.
        Canvas(
            modifier = Modifier
                .fillMaxSize()
                .onSizeChanged { canvasSize = it }
                .pointerInput(centers, nodeR) {
                    awaitPointerEventScope {
                        while (true) {
                            val event = awaitPointerEvent()
                            val pos = event.changes.firstOrNull()?.position
                            when (event.type) {
                                PointerEventType.Move, PointerEventType.Enter -> {
                                    hoveredNode = if (pos != null && nodeR > 0f) {
                                        centers.indexOfFirst { (it - pos).getDistance() <= nodeR * 1.2f }
                                            .takeIf { it >= 0 }
                                    } else null
                                }
                                PointerEventType.Press -> {
                                    if (pos != null && nodeR > 0f) {
                                        val hit = centers.indexOfFirst { (it - pos).getDistance() <= nodeR * 1.2f }
                                        if (hit >= 0) {
                                            event.changes.forEach { it.consume() }
                                            isCryptoMode = !isCryptoMode
                                        }
                                    }
                                }
                                PointerEventType.Release -> {
                                    if (pos != null && nodeR > 0f) {
                                        val hit = centers.indexOfFirst { (it - pos).getDistance() <= nodeR * 1.2f }
                                        if (hit >= 0) {
                                            event.changes.forEach { it.consume() }
                                        }
                                    }
                                }
                                PointerEventType.Exit -> {
                                    hoveredNode = null
                                }
                            }
                        }
                    }
                }
        ) {
            if (centers.size < n) return@Canvas

            // Arrows: i -> assignment[i], clipped to the node edges, with arrowheads.
            for (i in 0 until n) {
                val from = centers[i]
                val to = centers[assignment[i]]
                val d = to - from
                val len = d.getDistance()
                if (len > 1f) {
                    val dir = d / len
                    val start = from + dir * nodeR
                    val end = to - dir * nodeR
                    drawLine(arrowColor.copy(alpha = arrowT), start, end, strokeWidth = 2f)
                    val headLen = nodeR * 0.7f
                    val headW = nodeR * 0.5f
                    val perp = Offset(-dir.y, dir.x)
                    val tip = end
                    val base = end - dir * headLen
                    val path = Path().apply {
                        moveTo(tip.x, tip.y)
                        lineTo(base.x + perp.x * headW, base.y + perp.y * headW)
                        lineTo(base.x - perp.x * headW, base.y - perp.y * headW)
                        close()
                    }
                    drawPath(path, arrowColor.copy(alpha = arrowT))
                }
            }

            // Nodes. Normal mode shows the role avatar (image overlay in the Box below);
            // crypto/bits mode draws the 4-bit label here.
            for (i in 0 until n) {
                val c = centers[i]
                drawCircle(nodeFill, radius = nodeR, center = c)
                drawCircle(nodeBorder, radius = nodeR, center = c, style = Stroke(width = 2f))
                if (isCryptoMode) {
                    val layout = measurer.measure(
                        nodeBits[i],
                        TextStyle(
                            color = labelColor,
                            fontSize = 9.5.sp,
                            fontWeight = FontWeight.Bold,
                            fontFamily = FontFamily.Monospace
                        )
                    )
                    drawText(layout, topLeft = c - Offset(layout.size.width / 2f, layout.size.height / 2f))
                }
            }

            // Step 3 — highlight the 1->7 arrow: "easy to answer" (forward direction).
            if (step >= 3) {
                val from = centers[1]
                val to = centers[7]
                val d = to - from
                val len = d.getDistance()
                if (len > 1f) {
                    val dir = d / len
                    val start = from + dir * nodeR
                    val end = to - dir * nodeR
                    drawLine(easyColor.copy(alpha = easyT), start, end, strokeWidth = 4f)
                    val headLen = nodeR * 0.7f
                    val headW = nodeR * 0.5f
                    val perp = Offset(-dir.y, dir.x)
                    val base = end - dir * headLen
                    val head = Path().apply {
                        moveTo(end.x, end.y)
                        lineTo(base.x + perp.x * headW, base.y + perp.y * headW)
                        lineTo(base.x - perp.x * headW, base.y - perp.y * headW)
                        close()
                    }
                    drawPath(head, easyColor.copy(alpha = easyT))
                    val mid = (start + end) / 2f
                    val inward = Offset(cx, cy) - mid
                    val inLen = inward.getDistance()
                    val label = measurer.measure(
                        "easy to answer",
                        TextStyle(color = easyColor.copy(alpha = easyT), fontSize = 12.sp, fontWeight = FontWeight.Bold)
                    )
                    val labelPos = if (inLen > 1f) mid + inward / inLen * (nodeR * 4f) else mid
                    drawText(label, topLeft = labelPos - Offset(label.size.width / 2f, label.size.height / 2f))
                }
            }

            // Step 4 — curved 7->1 arrow: "impossible" (the inverse direction).
            if (step >= 4) {
                val from = centers[7]
                val to = centers[1]
                val d = to - from
                val len = d.getDistance()
                if (len > 1f) {
                    val dir = d / len
                    val start = from + dir * nodeR
                    val end = to + Offset(nodeR, 0f)              // node 1's RIGHT edge
                    val mid = (start + end) / 2f
                    val outward = mid - Offset(cx, cy)
                    val outLen = outward.getDistance()
                    val outDir = if (outLen > 1f) outward / outLen else Offset(-dir.y, dir.x)
                    val c1 = mid + outDir * (ringR * 0.45f)        // bulge outward
                    val c2 = end + Offset(ringR * 0.35f, 0f)        // arrive at node 1 from the right
                    val curve = Path().apply {
                        moveTo(start.x, start.y)
                        cubicTo(c1.x, c1.y, c2.x, c2.y, end.x, end.y)
                    }
                    drawPath(curve, impossibleColor.copy(alpha = impossibleT), style = Stroke(width = 3f))
                    // arrowhead: comes from the right, pointing left into node 1.
                    val adir = Offset(-1f, 0f)
                    val headLen = nodeR * 0.7f
                    val headW = nodeR * 0.5f
                    val perp = Offset(-adir.y, adir.x)
                    val base = end - adir * headLen
                    val head = Path().apply {
                        moveTo(end.x, end.y)
                        lineTo(base.x + perp.x * headW, base.y + perp.y * headW)
                        lineTo(base.x - perp.x * headW, base.y - perp.y * headW)
                        close()
                    }
                    drawPath(head, impossibleColor.copy(alpha = impossibleT))
                    val label = measurer.measure(
                        "impossible",
                        TextStyle(color = impossibleColor.copy(alpha = impossibleT), fontSize = 12.sp, fontWeight = FontWeight.Bold)
                    )
                    val labelPos = c2 + Offset(nodeR * 1.5f, 0f)
                    drawText(label, topLeft = labelPos - Offset(label.size.width / 2f, label.size.height / 2f))
                }
            }
        }

        // Role avatars — overlaid on the nodes in normal mode (hidden in crypto/bits mode).
        if (!isCryptoMode && centers.size == n) {
            val nodeDiameter = with(LocalDensity.current) { (nodeR * 2f).toDp() }
            centers.forEachIndexed { i, center ->
                Image(
                    painter = painterResource(roles[i].image),
                    contentDescription = roles[i].name,
                    contentScale = ContentScale.Crop,
                    modifier = Modifier
                        .offset {
                            IntOffset(
                                x = (center.x - nodeR).roundToInt(),
                                y = (center.y - nodeR).roundToInt()
                            )
                        }
                        .size(nodeDiameter)
                        .clip(CircleShape)
                )
            }
        }

        // Title — gift icon + "Secret Santa" (reuses the former corner gift icon).
        Row(
            modifier = Modifier.align(Alignment.TopCenter),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            Icon(
                imageVector = Icons.Default.CardGiftcard,
                contentDescription = null,
                modifier = Modifier.size(28.dp),
                tint = MaterialTheme.colorScheme.primary
            )
            Text(
                text = "Secret Santa",
                style = MaterialTheme.typography.headlineSmall,
                color = MaterialTheme.colorScheme.onSurface
            )
        }

        // Tooltip bubble on hover
        hoveredNode?.let { nodeIndex ->
            val center = centers.getOrNull(nodeIndex)
            if (center != null) {
                Box(
                    modifier = Modifier
                        .offset {
                            IntOffset(
                                x = center.x.roundToInt(),
                                y = (center.y - nodeR - 8f).roundToInt()
                            )
                        }
                        .layout { measurable, constraints ->
                            val placeable = measurable.measure(constraints)
                            layout(placeable.width, placeable.height) {
                                placeable.placeRelative(-placeable.width / 2, -placeable.height)
                            }
                        }
                        .background(
                            color = MaterialTheme.colorScheme.surfaceVariant,
                            shape = RoundedCornerShape(8.dp)
                        )
                        .border(
                            width = 1.dp,
                            color = MaterialTheme.colorScheme.outlineVariant,
                            shape = RoundedCornerShape(8.dp)
                        )
                        .padding(horizontal = 12.dp, vertical = 8.dp)
                ) {
                    Column(
                        horizontalAlignment = Alignment.Start,
                        verticalArrangement = Arrangement.spacedBy(2.dp)
                    ) {
                        if (!isCryptoMode) {
                            Text(
                                text = roles[nodeIndex].name,
                                style = MaterialTheme.typography.titleMedium,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.onSurfaceVariant,
                                modifier = Modifier.align(Alignment.CenterHorizontally)
                            )
                            Text(
                                text = buildAnnotatedString {
                                    append("Gives to: ")
                                    withStyle(SpanStyle(color = easyColor, fontWeight = FontWeight.Bold)) {
                                        append(roles[assignment[nodeIndex]].name)
                                    }
                                },
                                style = MaterialTheme.typography.bodySmall,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(6.dp)
                            ) {
                                Text(
                                    text = "Receives from:",
                                    style = MaterialTheme.typography.bodySmall,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                )
                                CircularProgressIndicator(
                                    modifier = Modifier.size(12.dp),
                                    color = impossibleColor,
                                    strokeWidth = 2.dp
                                )
                            }
                        } else {
                            val fromBits = nodeBits[nodeIndex]
                            val toBits = nodeBits[assignment[nodeIndex]]
                            Text(
                                text = buildAnnotatedString {
                                    append("encrypt($fromBits) = ")
                                    withStyle(SpanStyle(color = easyColor, fontWeight = FontWeight.Bold)) {
                                        append(toBits)
                                    }
                                },
                                style = MaterialTheme.typography.bodySmall,
                                color = MaterialTheme.colorScheme.onSurfaceVariant,
                                fontFamily = FontFamily.Monospace
                            )
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(6.dp)
                            ) {
                                Text(
                                    text = "decrypt($fromBits) =",
                                    style = MaterialTheme.typography.bodySmall,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                                    fontFamily = FontFamily.Monospace
                                )
                                CircularProgressIndicator(
                                    modifier = Modifier.size(12.dp),
                                    color = impossibleColor,
                                    strokeWidth = 2.dp
                                )
                            }
                        }
                    }
                }
            }
        }
    }
}
